package hyperuuid

// The one backend: the Rust core built for wasm32-wasip1 and translated to Go by wasm2go
// (internal/core/core.go, regenerated by `go generate` and diffed in CI). An instance is one
// translated module, its random source, and a scratch region in the module's linear memory
// where arguments are copied in and results copied out. The v7 counter lives in the module's
// memory, so uuid_new_v7 and uuid_new_v7_batch run on one primary instance behind its mutex;
// every other call carries no state and runs on the primary when its lock is free, else on a
// pooled instance (core_pool.go; under TinyGo everything serializes on the primary,
// core_tinygo.go).
//
// wasm2go's generated code bounds-checks every memory access and keeps the call stack in Go,
// so a core bug, a guest stack overflow included, is a Go panic and never a corrupted heap.
// The guest stack is 64 KiB: the smallest size that passes the whole suite, the memory
// receipts and the exhaustion package is 256 bytes and 128 traps, so the shipped size is a
// 256x margin over the tested paths (internal/wasm2go/main.go has the measurement).

import (
	"encoding/binary"
	"fmt"
	"math"
	"sync"
	"sync/atomic"
	"time"
	"unsafe"

	"github.com/SkunkWerkx/HyperUuid/go/internal/core"
	"github.com/google/uuid"
)

const pageSize = 65536

// basePages is the scratch of a fresh instance: one page, enough for every call but a batch
// or a v5 name longer than 65,504 bytes.
const basePages uint32 = 1

// hostMaxPages is the most pages a guest memory can hold here: WebAssembly's 65,536, or
// what the host's int can address on a 32-bit platform (the generated memory_grow applies
// the same cap).
const hostMaxPages = min(65536, math.MaxInt>>16)

// MaxV5Name is the longest name NewV5 takes, in bytes: the smaller of the guest's slice
// limit (2^31 − 1, isize::MAX on wasm32, which the core's slice::from_raw_parts must not
// exceed on any host) and the guest's address space less the instance's two base pages and
// the 32 bytes before the name, itself capped by the host's page limit on a 32-bit platform.
// On a 64-bit host it is 2,147,483,647. A longer name returns ErrNameTooLong before anything
// is allocated.
const MaxV5Name = min(1<<31-1, hostMaxPages*pageSize-2*pageSize-32)

// instancesCreated counts instances ever created, a hook for the tests that pin when a
// second instance is and is not made.
var instancesCreated atomic.Int64

type instance struct {
	mu      sync.Mutex
	m       *core.Module
	src     source
	scratch uint32 // byte offset of the scratch region in the module's memory
	pages   uint32 // pages the scratch holds; grows, never shrinks
}

// newInstance creates a module with pages of scratch beyond its own two pages. It reports
// false when the generated memory_grow refuses the growth (the page limits); a host that
// cannot allocate the pages is a runtime fatal, as the caller's own make would be.
func newInstance(pages uint32) (*instance, bool) {
	return newInstanceWith(pages, newSource(time.Now))
}

func newInstanceWith(pages uint32, src source) (*instance, bool) {
	in := &instance{src: src}
	in.m = core.New(in)
	old := in.m.Xmemory().Grow(int64(pages), hostMaxPages)
	if old < 0 {
		return nil, false
	}
	in.scratch = uint32(old) * pageSize
	in.pages = pages
	instancesCreated.Add(1)
	return in, true
}

// Xrandom_get is the WASI import the core calls: n bytes at ptr from this instance's
// source, 0 on success or the errno the source returns.
func (in *instance) Xrandom_get(ptr, n int32) int32 {
	return in.src.fill(in.mem()[ptr : ptr+n])
}

// mem is the module's memory now. Nothing caches it across a call: a grow replaces the
// slice.
func (in *instance) mem() []byte {
	return *in.m.Xmemory().Slice()
}

// scratchPagesFor is the pages a scratch of bytes needs, and whether an instance can hold
// them beside its two base pages. All arithmetic is in uint64 before any narrowing.
func scratchPagesFor(bytes uint64) (pages uint32, ok bool) {
	need := bytes / pageSize
	if bytes%pageSize != 0 {
		need++
	}
	if need+2 > hostMaxPages {
		return 0, false
	}
	return uint32(need), true
}

// ensureScratch grows the scratch to hold bytes, reporting false when the host or the guest
// cannot address that much.
func (in *instance) ensureScratch(bytes uint64) bool {
	need, ok := scratchPagesFor(bytes)
	if !ok {
		return false
	}
	if need <= in.pages {
		return true
	}
	if in.m.Xmemory().Grow(int64(need-in.pages), hostMaxPages) < 0 {
		return false
	}
	in.pages = need
	return true
}

var (
	primaryOnce sync.Once
	thePrimary  *instance
)

// primary is the instance that holds the v7 stream, created on first use so that importing
// the package costs nothing.
func primary() *instance {
	primaryOnce.Do(func() {
		in, ok := newInstance(basePages)
		if !ok {
			panic("hyperuuid: the core's memory cannot grow by one page on this host")
		}
		thePrimary = in
	})
	return thePrimary
}

// Available reports whether the core can be called. The core is compiled in, not loaded, so
// it always can; the function exists for parity with the bindings that load a library.
func Available() bool {
	return true
}

// LoadError returns the error that made the core unavailable: always nil, for the same
// reason Available is always true.
func LoadError() error {
	return nil
}

// NativeVersion returns the core's version as "major.minor.patch": the crate version
// compiled into the translated core.
func NativeVersion() string {
	v := packedVersion()
	return fmt.Sprintf("%d.%d.%d", v>>16, (v>>8)&0xFF, v&0xFF)
}

func packedVersion() uint32 {
	in, pooled := acquire()
	defer release(in, pooled)
	return uint32(in.m.Xhyperuuid_version())
}

// ErrNameTooLong error naming n and the limit.
func checkV5Name(n int) error {
	if n > MaxV5Name {
		return fmt.Errorf("hyperuuid: name of %d bytes exceeds MaxV5Name (%d): %w", n, MaxV5Name, ErrNameTooLong)
	}
	return nil
}

// ---- The calls uuidgen.go and inspect.go make --------------------------------------------
//
// Each acquires an instance (acquire/release: the primary when uncontended, else a pooled
// one; the primary always under TinyGo), copies its arguments into the scratch, calls the
// core with scratch offsets, and copies the result out; the memory slice is read after the
// call, never cached across it. No closures: TinyGo would heap-allocate them, and the
// zero-allocation tests run there too.

func newV4() (out uuid.UUID, rc int32) {
	in, pooled := acquire()
	defer release(in, pooled)
	rc = in.m.Xuuid_new_v4(int32(in.scratch))
	copy(out[:], in.mem()[in.scratch:])
	return out, rc
}

// v5 layout in the scratch: the namespace at 0, the output at 16, the name from 32.
const v5NameOffset = 32

func newV5(ns uuid.UUID, name []byte) (uuid.UUID, error) {
	need := uint64(len(name)) + v5NameOffset
	var out uuid.UUID
	var rc int32
	if need <= uint64(basePages)*pageSize {
		in, pooled := acquire()
		out, rc = in.v5(ns, name)
		release(in, pooled)
	} else {
		// A longer name runs on a one-off instance sized for it, so neither the primary nor
		// the pool retains the pages. It draws no entropy: its source is the OS one.
		pages, ok := scratchPagesFor(need)
		if !ok {
			return uuid.UUID{}, checkV5Name(len(name))
		}
		in, ok := newInstanceWith(pages, osSource{})
		if !ok {
			return uuid.UUID{}, fmt.Errorf("hyperuuid: the core cannot address a name of %d bytes on this host: %w", len(name), ErrNameTooLong)
		}
		out, rc = in.v5(ns, name)
	}
	if rc != 0 {
		return uuid.UUID{}, fmt.Errorf("uuid_new_v5 failed with code %d", rc)
	}
	return out, nil
}

// v5 runs uuid_new_v5 on an instance whose scratch holds the name.
func (in *instance) v5(ns uuid.UUID, name []byte) (out uuid.UUID, rc int32) {
	mem := in.mem()
	copy(mem[in.scratch:], ns[:])
	copy(mem[in.scratch+v5NameOffset:], name)
	s := int32(in.scratch)
	rc = in.m.Xuuid_new_v5(s, s+v5NameOffset, int32(len(name)), s+16)
	copy(out[:], in.mem()[in.scratch+16:])
	return out, rc
}

func newV7(unixMillis uint64) (out uuid.UUID, rc int32) {
	p := primary()
	p.mu.Lock()
	defer p.mu.Unlock()
	rc = p.m.Xuuid_new_v7(int64(unixMillis), int32(p.scratch))
	copy(out[:], p.mem()[p.scratch:])
	return out, rc
}

// newV7Batch mints count UUIDs into the primary's scratch, grown to hold them all (a batch
// is one reservation of the stream and is never chunked), then copies them to out. On a
// failure nothing is copied: out is untouched.
func newV7Batch(unixMillis uint64, count uint32, out unsafe.Pointer) int32 {
	p := primary()
	p.mu.Lock()
	defer p.mu.Unlock()
	n := uint64(count) * 16
	if !p.ensureScratch(n) {
		return 3 // the core's own code for a batch it cannot address
	}
	rc := p.m.Xuuid_new_v7_batch(int64(unixMillis), int32(count), int32(p.scratch))
	if rc == 0 {
		copy(unsafe.Slice((*byte)(out), n), p.mem()[p.scratch:])
	}
	return rc
}

// load copies id into the instance's scratch and returns its offset.
func (in *instance) load(id uuid.UUID) int32 {
	copy(in.mem()[in.scratch:], id[:])
	return int32(in.scratch)
}

// result is the 16 bytes at the scratch after a call.
func (in *instance) result() (out uuid.UUID) {
	copy(out[:], in.mem()[in.scratch:])
	return out
}

func v7UnixMillis(id uuid.UUID) uint64 {
	in, pooled := acquire()
	defer release(in, pooled)
	return uint64(in.m.Xuuid_v7_unix_millis(in.load(id)))
}

func v7ToSqlOrder(id uuid.UUID) (uuid.UUID, int32) {
	in, pooled := acquire()
	defer release(in, pooled)
	rc := in.m.Xuuid_v7_to_sql_order(in.load(id))
	return in.result(), rc
}

func v7ToRfcOrder(id uuid.UUID) (uuid.UUID, int32) {
	in, pooled := acquire()
	defer release(in, pooled)
	rc := in.m.Xuuid_v7_to_rfc_order(in.load(id))
	return in.result(), rc
}

// bytesInPlace runs one of the two conversions on a caller's 16-byte buffer, rewritten only
// on success: a refusal leaves it as it was.
func bytesInPlace(p unsafe.Pointer, convert func(uuid.UUID) (uuid.UUID, int32)) int32 {
	b := unsafe.Slice((*byte)(p), 16)
	out, rc := convert(uuid.UUID(b))
	if rc == 0 {
		copy(b, out[:])
	}
	return rc
}

func v7ToSqlOrderBytes(p unsafe.Pointer) int32 { return bytesInPlace(p, v7ToSqlOrder) }
func v7ToRfcOrderBytes(p unsafe.Pointer) int32 { return bytesInPlace(p, v7ToRfcOrder) }

func version(id uuid.UUID, layout uint32) uint32 {
	in, pooled := acquire()
	defer release(in, pooled)
	return uint32(in.m.Xuuid_version(in.load(id), int32(layout)))
}

func variant(id uuid.UUID) uint32 {
	in, pooled := acquire()
	defer release(in, pooled)
	return uint32(in.m.Xuuid_variant(in.load(id)))
}

func isRfc(id uuid.UUID, version, layout uint32) bool {
	in, pooled := acquire()
	defer release(in, pooled)
	return in.m.Xuuid_is_rfc(in.load(id), int32(version), int32(layout)) != 0
}

func v7UnixMillisIn(id uuid.UUID, layout uint32) uint64 {
	in, pooled := acquire()
	defer release(in, pooled)
	return uint64(in.m.Xuuid_v7_unix_millis_in(in.load(id), int32(layout)))
}

// getTimestamp returns the core's version answer (7, or 0 for not time-based) and the
// milliseconds it wrote to the 8-byte out parameter, which sits in the scratch after the UUID.
func getTimestamp(id uuid.UUID, layout uint32) (ver uint32, ms uint64) {
	in, pooled := acquire()
	defer release(in, pooled)
	s := in.load(id)
	ver = uint32(in.m.Xuuid_get_timestamp(s, int32(layout), s+16))
	ms = binary.LittleEndian.Uint64(in.mem()[in.scratch+16:])
	return ver, ms
}
